import{_ as a,o as e,c as i,a5 as n,j as o,t as r}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Trend Detection & Content Generation — GraphRAG + Streaming Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"idea/crawl-data-algorithm/crawl-data-analysis.md","filePath":"idea/crawl-data-algorithm/crawl-data-analysis.md"}'),h={name:"idea/crawl-data-algorithm/crawl-data-analysis.md"};function c(s,t,l,d,p,g){return e(),i("div",null,[t[0]||(t[0]=n(`<h1 id="trend-detection-content-generation-—-graphrag-streaming-analysis" tabindex="-1">Trend Detection &amp; Content Generation — GraphRAG + Streaming Analysis <a class="header-anchor" href="#trend-detection-content-generation-—-graphrag-streaming-analysis" aria-label="Permalink to &quot;Trend Detection &amp; Content Generation — GraphRAG + Streaming Analysis&quot;">​</a></h1><p>Nguồn: <code>crawData.m4a</code> (transcript by user 2026-07-02).</p><h2 id="_1-tom-tat-y-tuong" tabindex="-1">1. Tóm tắt ý tưởng <a class="header-anchor" href="#_1-tom-tat-y-tuong" aria-label="Permalink to &quot;1. Tóm tắt ý tưởng&quot;">​</a></h2><p>Hệ thống crawl data (video/audio/text đa nguồn) → giải mã về text chuẩn → phân tích trend real-time → sinh prompt content cho AI generation. Kiến trúc chất = <strong>GraphRAG</strong> (Graph DB + Vector DB) kết hợp <strong>streaming data analysis</strong> bắt trend theo thời gian thực.</p><h2 id="_2-data-pipeline" tabindex="-1">2. Data Pipeline <a class="header-anchor" href="#_2-data-pipeline" aria-label="Permalink to &quot;2. Data Pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Crawl (video/audio/text) → Speech-to-Text (Whisper local, RTX 4050) →</span></span>
<span class="line"><span>Text normalize → Embedding (open-source model) →</span></span>
<span class="line"><span>  ├─ Vector DB (semantic search)</span></span>
<span class="line"><span>  └─ Graph DB (entity relationship)</span></span>
<span class="line"><span>→ BM25 keyword scoring → Prune low-score nodes → Context assembly → LLM prompt</span></span></code></pre></div><ul><li>STT chạy local trên RTX 4050 (Whisper) — giảm phụ thuộc API trả phí.</li><li>Backend: Spring Boot hoặc Node.js — quản lý background crawl jobs + xử lý luồng data lớn hàng ngày.</li></ul><h2 id="_3-bm25-—-keyword-scoring" tabindex="-1">3. BM25 — keyword scoring <a class="header-anchor" href="#_3-bm25-—-keyword-scoring" aria-label="Permalink to &quot;3. BM25 — keyword scoring&quot;">​</a></h2><p>Chọn BM25 thay TF-IDF: giải quyết term frequency saturation, phạt văn bản dài, trích trending keyword chính xác hơn.</p>`,9)),o("p",null,"$$ \\text{score}(D, Q) = \\sum_{i=1}^{n} \\text{IDF}(q_i) \\cdot \\frac{f(q_i, D) \\cdot (k_1 + 1)}{f(q_i, D) + k_1 \\cdot \\left(1 - b + b \\cdot \\frac{|D|}{\\text{avgdl"+r("}}")+"\\right)} $$",1),t[1]||(t[1]=n('<p>Dùng để: rank keyword trend, prune node trước khi đẩy vào LLM context (tránh vượt token limit).</p><h2 id="_4-storage-graph-db-vs-vector-db" tabindex="-1">4. Storage: Graph DB vs Vector DB <a class="header-anchor" href="#_4-storage-graph-db-vs-vector-db" aria-label="Permalink to &quot;4. Storage: Graph DB vs Vector DB&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Đặc điểm</th><th>Graph DB (Neo4j)</th><th>Vector DB (Milvus/Qdrant)</th><th>Kết hợp (GraphRAG)</th></tr></thead><tbody><tr><td>Thế mạnh</td><td>Quan hệ logic (A liên kết B)</td><td>Semantic search theo ý định</td><td>Semantic search → trích mạng lưới liên quan</td></tr><tr><td>Điểm yếu</td><td>Không hiểu ngữ nghĩa tương đồng</td><td>Mất ngữ cảnh tuyến tính/liên kết</td><td>Pipeline phức tạp, chi phí cao</td></tr><tr><td>Vai trò</td><td>Tìm entity liên kết mạnh trong cùng trend</td><td>Match prompt user (&quot;gợi ý trend đồ ăn&quot;)</td><td>Trả prompt đủ sâu — keyword + context sự kiện</td></tr></tbody></table><p>Quyết định: không chọn 1 trong 2 — kết hợp cả hai (chuẩn kiến trúc Agentic AI long-term memory hiện tại).</p><h2 id="_5-thach-thuc-can-giai" tabindex="-1">5. Thách thức cần giải <a class="header-anchor" href="#_5-thach-thuc-can-giai" aria-label="Permalink to &quot;5. Thách thức cần giải&quot;">​</a></h2><h3 id="_5-1-entity-resolution-chuan-hoa-thuc-the" tabindex="-1">5.1 Entity Resolution (chuẩn hóa thực thể) <a class="header-anchor" href="#_5-1-entity-resolution-chuan-hoa-thuc-the" aria-label="Permalink to &quot;5.1 Entity Resolution (chuẩn hóa thực thể)&quot;">​</a></h3><p>Graph phình to mỗi ngày → node trùng ngữ nghĩa (vd &quot;Trấn Thành&quot; vs &quot;MC Trấn Thành&quot;). Cần cơ chế merge node — tránh rác Knowledge Graph.</p><p><strong>Hướng giải:</strong> entity linking bằng embedding similarity + alias dictionary, hoặc LLM-based entity resolution job chạy định kỳ.</p><h3 id="_5-2-đo-tre-token-limit" tabindex="-1">5.2 Độ trễ / Token limit <a class="header-anchor" href="#_5-2-đo-tre-token-limit" aria-label="Permalink to &quot;5.2 Độ trễ / Token limit&quot;">​</a></h3><p>Ghép nhiều node thành context dài → vượt context window hoặc chậm response.</p><p><strong>Hướng giải:</strong> prune theo điểm BM25 trước khi build context; giới hạn depth traversal trong graph; cache context đã build cho trend phổ biến.</p><h3 id="_5-3-ban-chat-thuat-toan-nen-tang-tiktok-facebook" tabindex="-1">5.3 Bản chất thuật toán nền tảng (TikTok/Facebook) <a class="header-anchor" href="#_5-3-ban-chat-thuat-toan-nen-tang-tiktok-facebook" aria-label="Permalink to &quot;5.3 Bản chất thuật toán nền tảng (TikTok/Facebook)&quot;">​</a></h3><p>Nền tảng đánh giá không chỉ qua keyword mà qua Retention Rate. Prompt sinh ra cần có SEO keyword + &quot;hook&quot; 3 giây đầu.</p><p><strong>Hướng giải:</strong> thêm scoring layer riêng cho &quot;hook strength&quot; khi build prompt — không chỉ trend keyword mà cả structure gợi ý (câu mở đầu, pattern giữ chân).</p><h2 id="_6-viec-can-lam-tiep-open-items" tabindex="-1">6. Việc cần làm tiếp (open items) <a class="header-anchor" href="#_6-viec-can-lam-tiep-open-items" aria-label="Permalink to &quot;6. Việc cần làm tiếp (open items)&quot;">​</a></h2><ul><li>[ ] Chọn Graph DB cụ thể (Neo4j vs alt) — cân nhắc chi phí vận hành trên infra hiện có</li><li>[ ] Chọn Vector DB (Milvus/Qdrant) — check tương thích brandhub-ai-service</li><li>[ ] Thiết kế entity resolution pipeline (merge node)</li><li>[ ] Thiết kế prune strategy (BM25 threshold, depth limit)</li><li>[ ] Thiết kế &quot;hook scoring&quot; cho prompt generation</li><li>[ ] POC: Whisper local trên RTX 4050 — đo tốc độ/độ chính xác thực tế</li></ul>',16))])}const k=a(h,[["render",c]]);export{m as __pageData,k as default};
